variantOf.overrides:
{
  striped: true,
  hoverable: true,
  stickyHeader: true,
  fill: true,
}

{
  gap: "sm",
  style: {
    width: "400px",
    "min-width": "400px",
    "max-width": "400px",
    "align-self": "stretch",
    "border-right": "1px solid var(--sui-border)",
    padding: "12px",
    "box-sizing": "border-box",
    "overflow-y": "auto",
  },
}

{
  variant: "label",
  as: "span",
  // `inherit`, not a token: a callout caption takes the tone of the callout it
  // belongs to, which its SVG parent already carries. Without this the
  // `label` variant's own `color` would paint over that inheritance.
  color: "inherit",
  style: {
    "font-size": "11px",
    "font-weight": "600",
    "line-height": "1.2",
    "text-transform": "uppercase",
    "letter-spacing": "0.5px",
    display: "block",
    "min-width": "0",
    overflow: "hidden",
    "white-space": "nowrap",
    "text-overflow": "ellipsis",
  },
}

{
  align: "center",
  wrap: true,
  gap: "xs",
  style: { flex: "1", "min-width": "0" },
}

{
  variant: "value",
  as: "pre",
  style: {
    "font-family": '"JetBrains Mono", "Fira Code", monospace',
    "font-size": "10px",
    "white-space": "pre",
    margin: "0",
  },
}

{
    band: [0.05, 0.95],
    marks: { range: true, typical: true, mean: true },
  }

{
  style: {
    background: "var(--sui-bg-primary)",
    width: "100%",
    height: "100%",
    margin: "0",
    padding: "0",
  },
}

{
    labels: {
      reference: "Baseline",
      versus: "vs",
      save: "Save",
      reset: "Reset to saved",
      deleteItem: (label) => `Delete ${label}`,
    },
  }

{
  rows: [
    [["name"], ["dots"]],
    [
      [{ slot: "string", prio: 2 }],
      [{ slot: "date", prio: 2 }],
      [{ slot: "duration", prio: 2 }],
    ],
  ],
}
